package main

import (
	"encoding/json"
	"fmt"
	"log"
)

type Address struct {
	Street string `json:"street"`
	City   string `json:"city"`
	Zip    string `json:"zip"`
}

type User struct {
	ID       int     `json:"id"`
	Username string  `json:"username"`
	Email    string  `json:"email"`
	Password string  `json:"-"`
	Age      int     `json:"age,omitempty"`
	Address  Address `json:"address"`
	Tags     []string `json:"tags,omitempty"`
}

type APIResponse struct {
	Success bool        `json:"success"`
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

func main() {
	// Marshal: struct -> JSON
	user := User{
		ID:       1,
		Username: "alice",
		Email:    "alice@example.com",
		Password: "secret123",
		Age:      30,
		Address: Address{
			Street: "Jl. Sudirman 1",
			City:   "Jakarta",
			Zip:    "10220",
		},
		Tags: []string{"admin"},
	}

	data, err := json.MarshalIndent(user, "", "  ")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("Marshal output:")
	fmt.Println(string(data))

	// Unmarshal: JSON -> struct
	jsonStr := `{"id":2,"username":"bob","email":"bob@example.com","address":{"street":"Jl. Gatot 5","city":"Bandung","zip":"40000"}}`
	var user2 User
	if err := json.Unmarshal([]byte(jsonStr), &user2); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("\nUnmarshal: %s lives in %s\n", user2.Username, user2.Address.City)

	// API response
	resp := APIResponse{
		Success: true,
		Code:    200,
		Message: "User fetched",
		Data:    user,
	}
	respData, _ := json.MarshalIndent(resp, "", "  ")
	fmt.Println("\nAPI Response:")
	fmt.Println(string(respData))
}
